                                                                                    if (nomm) {
                                                                                        no = "mm";
                                                                                    }
                                                                                    var valinch = "";
                                                                                    console.log('das')
                                                                                    if (noinch) {
                                                                                        valinch = "inch";
                                                                                    }

                                                                                    //var rim = $("#cymainmm"+id).prop('checked').val();
                                                                                    //var rim = $("#cymainmm"+id).val();
                                                                                    console.log(no)
                                                                                    console.log(nomm)


                                                                                    var lowmm = $("#rollermeaAmmlow").val();
                                                                                    var highmm = $("#rollermeaAmmhigh").val();
