    <!-- head radio button approve/reject -->
    <script type="text/javascript">
        /*Model serial no*/
        $('#approved').change(function() {
            //alert(1);
          $(".commentapr").show();
          $(".commentrgt").hide();

            //console.log(model);

        });
        $('#rejected').change(function() {
           // alert(1);
            $(".commentapr").hide();
            $(".commentrgt").show();
            $(".commentrgt").prop("disabled".false);


            //console.log(model);

        });

    </script>




